CREATE DATABASE IF NOT EXISTS bitedash;
USE bitedash;
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('CUSTOMER','ADMIN') DEFAULT 'CUSTOMER', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE restaurants (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, cuisine VARCHAR(100), address VARCHAR(255), image_url VARCHAR(500), rating DECIMAL(2,1) DEFAULT 0, delivery_minutes VARCHAR(30), is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE food_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, restaurant_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, description VARCHAR(500), category VARCHAR(80), price DECIMAL(10,2) NOT NULL, image_url VARCHAR(500), is_available BOOLEAN DEFAULT TRUE, FOREIGN KEY (restaurant_id) REFERENCES restaurants(id));
CREATE TABLE orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, delivery_address VARCHAR(500) NOT NULL, total_amount DECIMAL(10,2) NOT NULL, status ENUM('PLACED','CONFIRMED','PREPARING','OUT_FOR_DELIVERY','DELIVERED','CANCELLED') DEFAULT 'PLACED', ordered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, food_item_id BIGINT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (food_item_id) REFERENCES food_items(id));
CREATE TABLE reviews (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, restaurant_id BIGINT NOT NULL, rating TINYINT NOT NULL CHECK (rating BETWEEN 1 AND 5), comment VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id));
